const int directions[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int S, T, total=1, n, tt, inf, b[1000], q[1000000], a[1000000][3], dep[20][20], dis[20][20], p[20][20], s[20][20];
char ma[20][20], mb[20][20];

void addEdge(int x, int y, int c) {
    a[++total][0]=y; a[total][1]=c; a[total][2]=b[x]; b[x]=total;
    a[++total][0]=x; a[total][1]=0; a[total][2]=b[y]; b[y]=total;
}

void bfs(int x0, int y0, bool check) {
    int l=1, r=1, id=p[x0][y0];
    q[l]=x0*1000 + y0;
    memset(dis, 63, sizeof(dis));
    inf=dis[0][0];
    dis[x0][y0]=0;
    while (l<=r) {
        int x=q[l]/1000, y=q[l]%1000; l++;
        if (check && s[x][y]!=0 && dis[x][y]<=tt && dis[x][y]<=dep[x][y])
            addEdge(id, s[x][y], inf);
        if (dis[x][y]>tt || dis[x][y]>=dep[x][y]) continue;
        if (id==3 && s[x][y]==9) printf("%d\n", dis[x][y]);
        for (int i=0; i<4; i++) {
