            if (nx>0 && nx<=n && ny>0 && ny<=n && isdigit(ma[nx][ny]) && dis[nx][ny]==inf) {
                dis[nx][ny]=dis[x][y]+1;
                q[++r]=nx*1000+ny;
            }
        }
    }
}

int d[1000];

bool build() {
    memset(d, 0, sizeof(d));
    int l=1, r=1; q[l]=S; d[S]=1;
    while (l<=r) {
        int x=q[l++]; 
        for (int i=b[x]; i; i=a[i][2]) {
            int y=a[i][0];
            if (d[y] || !a[i][1]) continue;
            d[y]=d[x]+1; q[++r]=y;
            if (y==T) return true;
        }
    }
    return false;
}

int dinic(int x, int flow) {
    if (x==T) return flow;
    int k=flow;
    for (int i=b[x]; i; i=a[i][2]) {
        int y=a[i][0];
        if (d[y]!=d[x]+1 || !a[i][1]) continue;
        int t=dinic(y, min(k, a[i][1]));
        k-=t; a[i][1]-=t; a[i^1][1]+=t;
        if (k==0) return flow;
    }
    if (k==flow) d[x]=-1;
    return flow - k;
}

