import java.util.*;
import java.io.*;

public class Main {
    static final int[][] directions = {{-1,0},{1,0},{0,-1},{0,1}};
    static int S, T, total=1, n, tt, inf, b[], q[], a[][], dep[][], dis[][], p[][], s[][];
    static char ma[][], mb[][];
    static final int MAX_N = 20;
    static final int MAX_TOTAL = 1000;
    static final int MAX_Q = 1000000;

    static class Edge {
        int to, capacity, rev;
        Edge(int to, int capacity, int rev) {
            this.to = to;
            this.capacity = capacity;
            this.rev = rev;
        }
    }

    static ArrayList<Edge>[] graph;

    static void addEdge(int x, int y, int c) {
        graph[x].add(new Edge(y, c, graph[y].size()));
        graph[y].add(new Edge(x, 0, graph[x].size() - 1));
    }

    static void bfs(int x0, int y0, boolean check) {
        int l=0, r=0, id=p[x0][y0];
        q[r++]=x0*1000 + y0;
        for (int[] row : dis) Arrays.fill(row, Integer.MAX_VALUE);
        dis[x0][y0]=0;
        while (l<r) {
            int val=q[l++];
            int x=val/1000, y=val%1000;
            if (check && s[x][y]!=0 && dis[x][y]<=tt && dis[x][y]<=dep[x][y])
                addEdge(id, s[x][y], inf);
            if (dis[x][y]>tt || dis[x][y]>=dep[x][y]) continue;
            if (id==3 && s[x][y]==9) System.out.println(dis[x][y]);
            for (int i=0; i<4; i++) {
                int nx=x+directions[i][0], ny=y+directions[i][1];
                if (nx>0 && nx<=n && ny>0 && ny<=n && Character.isDigit(ma[nx][ny]) && dis[nx][ny]==Integer.MAX_VALUE) {
                    dis[nx][ny]=dis[x][y]+1;
                    q[r++]=nx*1000+ny;
                }
            }
        }
    }

    static int[] d = new int[MAX_TOTAL+1];

    static boolean build() {
        Arrays.fill(d, 0);
        int l=0, r=0;
        q[r++]=S; d[S]=1;
        while (l<r) {
            int x=q[l++];
            for (Edge e : graph[x]) {
                int y=e.to;
                if (d[y]!=0 || e.capacity==0) continue;
                d[y]=d[x]+1; q[r++]=y;
                if (y==T) return true;
            }
        }
        return false;
    }

    static int dinic(int x, int flow) {
        if (x==T) return flow;
        int k=flow;
        for (Edge e : graph[x]) {
            int y=e.to;
            if (d[y]!=d[x]+1 || e.capacity==0) continue;
            int t=dinic(y, Math.min(k, e.capacity));
            if (t>0) {
                e.capacity -= t;
                graph[y].get(e.rev).capacity += t;
                k -= t;
                if (k==0) break;
            }
        }
        if (k==flow) d[x]=-1;
        return flow - k;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer(br.readLine());
        n=Integer.parseInt(st.nextToken());
        tt=Integer.parseInt(st.nextToken());
        ma=new char[MAX_N+1][MAX_N+1];
        mb=new char[MAX_N+1][MAX_N+1];
        dep=new int[MAX_N+1][MAX_N+1];
        dis=new int[MAX_N+1][MAX_N+1];
        p=new int[MAX_N+1][MAX_N+1];
        s=new int[MAX_N+1][MAX_N+1];

        for (int i=1; i<=n; i++) {
            String line=br.readLine();
            for (int j=1; j<=n; j++) {
                ma[i][j]=line.charAt(j-1);
            }
        }
        for (int i=1; i<=n; i++) {
            String line=br.readLine();
            for (int j=1; j<=n; j++) {
                mb[i][j]=line.charAt(j-1);
            }
        }

        for (int i=0; i<=MAX_N; i++) {
            Arrays.fill(dep[i], Integer.MAX_VALUE);
            Arrays.fill(dis[i], Integer.MAX_VALUE);
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (ma[i][j]=='Z') {
                    bfs(i,j,false);
                }
            }
        }
        for (int i=0; i<=MAX_N; i++) {
            for (int j=0; j<=MAX_N; j++) {
                dep[i][j]=dis[i][j];
            }
        }

        int t=1;
        S=0; T=1;
        graph=new ArrayList[MAX_TOTAL+2];
        for (int i=0; i<=MAX_TOTAL+1; i++) {
            graph[i]=new ArrayList<>();
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (ma[i][j]>'0' && ma[i][j]<='9') {
                    p[i][j]=++t;
                    addEdge(S, p[i][j], ma[i][j]-'0');
                }
                if (mb[i][j]>'0' && mb[i][j]<='9') {
                    s[i][j]=++t;
                    addEdge(s[i][j], T, mb[i][j]-'0');
                }
            }
        }

        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (p[i][j]!=0) {
                    bfs(i,j,true);
                }
            }
        }

        int ans=0;
        while (build()) {
            int flow;
            while ((flow=dinic(S, Integer.MAX_VALUE))>0) {
                ans+=flow;
            }
        }
        System.out.println(ans);
    }
}
